insert into public.reviews (id, name, avatar, rating, date, content) values (1, 'Nguyễn Minh Thư', 'https://placehold.co/80x80/F6CE8B/1B4B5A?text=MT', 5, '15/09/2026', 'Bánh ngon thật sự! Mình đặt bánh sinh nhật cho mẹ, team Cari tư vấn rất tận tình và bánh ra lò đúng như ý. Kem không quá ngọt, bánh bông xốp. Chắc chắn sẽ quay lại!') on conflict (id) do nothing;
insert into public.reviews (id, name, avatar, rating, date, content) values (2, 'Trần Hoàng Nam', 'https://placehold.co/80x80/1B4B5A/FCE9C6?text=HN', 5, '02/09/2026', 'Croissant bơ Pháp ở đây đỉnh lắm, lớp vỏ giòn rụm mà bên trong mềm thơm. Giao hàng nhanh, đóng gói cẩn thận. Mua lần đầu dùng mã CARI10 được giảm ngay, rất thích!') on conflict (id) do nothing;
insert into public.reviews (id, name, avatar, rating, date, content) values (3, 'Lê Bảo Châu', 'https://placehold.co/80x80/C97B3D/FFF8EF?text=BC', 5, '28/08/2026', 'Không gian ảo nhưng chất lượng thật. Tiramisu cá ly của Cari là ngon nhất mình từng ăn ở Hà Nội. Hương cà phê đậm đà, kem mascarpone mịn. Đặt hàng online siêu tiện.') on conflict (id) do nothing;
insert into public.site_content (key, value) values ('home', '{"heroSlides":[{"id":1,"image":"https://images.unsplash.com/photo-1509440159596-0249088772ff?w=1920&auto=format&fit=crop&q=80","title":"Bánh tươi thơm từ lò","ctaLabel":"Khám phá ngay","ctaHref":"/san-pham","showText":false},{"id":2,"image":"https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=1920&auto=format&fit=crop&q=80","title":"Bánh đặt theo yêu cầu","ctaLabel":"Đặt bánh ngay","ctaHref":"/dat-theo-yeu-cau","showText":false},{"id":3,"image":"https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=1920&auto=format&fit=crop&q=80","title":"Giảm 10% đơn đầu tiên","ctaLabel":"Mua ngay","ctaHref":"/san-pham","showText":false}],"features":[{"id":"points","title":"Chương trình tích điểm"},{"id":"delivery","title":"Giao hàng tận nơi"},{"id":"preorder","title":"Đặt trước"}],"banners":[{"label":"Bánh","href":"/san-pham?danh-muc=banh","image":"https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=800&auto=format&fit=crop&q=80"},{"label":"Đồ uống","href":"/san-pham?danh-muc=do-uong","image":"https://images.unsplash.com/photo-1517256064527-09c73fc73e38?w=800&auto=format&fit=crop&q=80"}],"topOrderSlugs":["banh-bong-lan-mat-ong","eclair-ca-phe-so-co-la","matcha-roll-cake"],"menuSlugs":["banh-sua-chua-chanh-leo","croissant-bo-phap","tart-trung-hong-kong","banh-su-kem-vanilla","tra-sua-tran-chau-cari","ca-phe-sua-da-cari","banh-red-velvet","tiramisu-ca-ly"],"gallery":[{"id":1,"image":"https://placehold.co/600x600/F6CE8B/1B4B5A?text=Gallery+1","alt":"Không gian cửa hàng Cari Bakehouse"},{"id":2,"image":"https://placehold.co/600x600/1B4B5A/FFF8EF?text=Gallery+2","alt":"Bánh tươi mỗi ngày"},{"id":3,"image":"https://placehold.co/600x600/C97B3D/FFF8EF?text=Gallery+3","alt":"Eclair sô cô la thơm lừng"},{"id":4,"image":"https://placehold.co/600x600/123640/FCE9C6?text=Gallery+4","alt":"Quầy bánh Cari"},{"id":5,"image":"https://placehold.co/600x600/FCE9C6/1B4B5A?text=Gallery+5","alt":"Bếp làm bánh thủ công"},{"id":6,"image":"https://placehold.co/600x600/E5D9C3/1B4B5A?text=Gallery+6","alt":"Đóng gói bánh tặng quà"}],"about":{"image":"https://images.unsplash.com/photo-1517433670267-08bbd4be890f?w=900&auto=format&fit=crop&q=80","badge":"Tiệm bánh thủ công từ 2024","quote":"Cari bắt đầu từ một tình yêu rất đơn giản: thích làm bánh và thích nhìn mọi người ăn bánh mình làm. Tụi mình làm bánh với mong muốn mang đến những món ngọt thật dễ thương, thật ngon và đủ gần gũi để bạn có thể ghé Cari bất cứ khi nào muốn tự thưởng cho mình một chút ngọt ngào."},"featuredReviewIds":[1,2,3]}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('about', '{"storyBadge":"Câu chuyện của Cari","storyTitle":"Vun vén ngọt ngào từ những điều giản dị","storyBody":"Cari bắt đầu từ một tình yêu rất đơn giản: thích làm bánh và thích nhìn mọi người ăn bánh mình làm. Tụi mình làm bánh với mong muốn mang đến những món ngọt thật dễ thương, thật ngon và đủ gần gũi để bạn có thể ghé Cari bất cứ khi nào muốn tự thưởng cho mình một chút ngọt ngào.","values":[{"icon":"shield","title":"Nguyên liệu chất lượng","desc":"Ưu tiên nguyên liệu sạch và an toàn cho từng chiếc bánh"},{"icon":"heart","title":"Chăm chút từng bước nhỏ","desc":"Từ khâu chọn nguyên liệu đến hoàn thiện, đều được làm cẩn thận"},{"icon":"clock","title":"Làm mới mỗi ngày","desc":"Bánh được sản xuất tươi theo đơn hàng ngày"},{"icon":"calendar","title":"Đồng hành mọi khoảnh khắc","desc":"Từ một miếng bánh sau bữa ăn đến một chiếc bánh sinh nhật, Cari. luôn ở đó"}],"faq":[{"question":"Cari Bakehouse giao hàng khu vực nào?","answer":"Giao hàng tận nơi trong toàn khu vực Hà Nội, thời gian giao cụ thể sẽ được thông báo khi xác nhận đơn."},{"question":"Phí giao hàng tính như thế nào?","answer":"Với đơn đặt qua các nền tảng như Shopeefood, Grabfood, phí ship tính theo chính sách nền tảng đó. Với đơn đặt trực tiếp ngoài nền tảng, phí ship tính theo ứng dụng Aha."},{"question":"Bánh lớn/đặt theo yêu cầu cần đặt trước bao lâu?","answer":"Đặt trước tối thiểu 12 tiếng đối với bánh kích thước lớn, và cần thanh toán trước khi tiệm bắt đầu làm bánh. Đơn xác nhận sau khi hai bên thống nhất thiết kế, số lượng và đặt cọc (nếu có)."},{"question":"Có cần đặt cọc khi mua bánh không?","answer":"Bánh thường (sản xuất hàng ngày) không yêu cầu đặt cọc. Với bánh đặc biệt/đặt riêng, tiệm yêu cầu cọc trước 100% giá trị đơn."},{"question":"Cari Bakehouse có nhận đổi/trả bánh không?","answer":"Tiệm không nhận đổi/trả nếu khách đổi ý sau khi đã xác nhận đơn. Chỉ hỗ trợ đổi/trả/hoàn tiền khi giao sai bánh, bánh bị hư hỏng do vận chuyển, hoặc lỗi chất lượng từ khâu sản xuất. Khách cần gửi khiếu nại kèm ảnh chụp trong vòng 2-4 tiếng sau khi nhận hàng, tiệm phản hồi trong vòng 24 giờ."},{"question":"Thanh toán bằng cách nào?","answer":"Chuyển khoản, tiền mặt khi nhận hàng (COD tại khu vực hỗ trợ), hoặc thanh toán trực tiếp tại cửa hàng."}]}'::jsonb) on conflict (key) do nothing;
